// checks: expSyms=86 expRng=40608 referenceMode=0 interpFilter=0

/// One traced HW decode of a global-motion frame vs SW. Success = full frame
/// in-sync (HW symbol count == SW, matching per-symbol rng, matching end rng).
Future<void> runGlobalMotionFrame({
  required int target,
  required int expSyms,
  required int expRng,
  required int maxBytes,
  required List<int> txCoeffSizes,
}) async {
  const ms = HarborInterFrameWalk.maxSyms;
  const nctx = HarborInterFrameWalk.numCtx;

  final t = HarborInterFrameWalk(
    maxBytes: maxBytes,
    txCoeffSizes: txCoeffSizes,
    enableTmvp: true,
    enableGlobalMotion: true,
  );
  final clk = SimpleClockGenerator(10).clk;
  final reset = Logic(name: 'reset');
  final start = Logic(name: 'start');
  final bytes = Logic(name: 'bytes', width: maxBytes * 8);
  final allowHp = Logic(name: 'allow_hp');
  final forceInt = Logic(name: 'force_int');
  final txModeSel = Logic(name: 'tx_mode_select');
  final skipModePresent = Logic(name: 'skip_mode_present');
  final refModeSelect = Logic(name: 'ref_mode_select');
  final skipRef0 = Logic(name: 'skip_ref0', width: 3);
  final skipRef1 = Logic(name: 'skip_ref1', width: 3);
  final maskedEn = Logic(name: 'enable_masked_compound');
  final mmSwitch = Logic(name: 'mm_switchable');
  final allowWarp = Logic(name: 'allow_warped_motion');
  final enableII = Logic(name: 'enable_interintra');
  final signBias = Logic(name: 'sign_bias', width: 8);
  final cdfIn = Logic(name: 'cdf_in', width: nctx * ms * 16);
  final nsymsIn = Logic(name: 'nsyms_in', width: nctx * 5);
  final gmType = Logic(name: 'gm_type', width: 7 * 2);
  final gmMat = Logic(name: 'gm_mat', width: 7 * 6 * 32);
  final useRefMvs = Logic(name: 'use_ref_frame_mvs');
  final tplValid = Logic(name: 'tpl_valid', width: 64);
  final tplMvRow = Logic(name: 'tpl_mvrow', width: 64 * 16);
  final tplMvCol = Logic(name: 'tpl_mvcol', width: 64 * 16);
  final tplRefOff = Logic(name: 'tpl_refoff', width: 64 * 6);
  final curOff = Logic(name: 'cur_off', width: 7 * 8);

  void conn(String p, Logic s) => t.input(p).srcConnection! <= s;
  conn('clk', clk);
  conn('reset', reset);
  conn('start', start);
  conn('bytes', bytes);
  conn('allow_hp', allowHp);
  conn('force_integer_mv', forceInt);
  conn('tx_mode_select', txModeSel);
  conn('skip_mode_present', skipModePresent);
  conn('ref_mode_select', refModeSelect);
  conn('skip_ref0', skipRef0);
  conn('skip_ref1', skipRef1);
  conn('enable_masked_compound', maskedEn);
  conn('mm_switchable', mmSwitch);
  conn('allow_warped_motion', allowWarp);
  conn('enable_interintra', enableII);
  conn('sign_bias', signBias);
  conn('cdf_in', cdfIn);
  conn('nsyms_in', nsymsIn);
  conn('gm_type', gmType);
  conn('gm_mat', gmMat);
  conn('use_ref_frame_mvs', useRefMvs);
  conn('tpl_valid', tplValid);
  conn('tpl_mvrow', tplMvRow);
  conn('tpl_mvcol', tplMvCol);
  conn('tpl_refoff', tplRefOff);
  conn('cur_off', curOff);
  await t.build();

  reset.inject(1);
  start.inject(0);
  bytes.inject(_bytesPk);
  allowHp.inject(_allowHp);
  forceInt.inject(_forceInt);
  txModeSel.inject(_txModeSel);
  skipModePresent.inject(_skipModePresent);
  refModeSelect.inject(_refModeSelect);
  skipRef0.inject(_skipRef0);
  skipRef1.inject(_skipRef1);
  maskedEn.inject(_maskedEn);
  mmSwitch.inject(_mmSwitch);
  allowWarp.inject(_allowWarp);
  enableII.inject(_enableII);
  signBias.inject(_signBias);
  cdfIn.inject(_cdfPk);
  nsymsIn.inject(_nsymsPk);
  gmType.inject(_gmTypePk);
  gmMat.inject(_gmMatPk);
  useRefMvs.inject(_useRefMvs);
  tplValid.inject(_tplValidPk);
  tplMvRow.inject(_tplRowPk);
  tplMvCol.inject(_tplColPk);
  tplRefOff.inject(_tplOffPk);
  curOff.inject(_curOffPk);

  Simulator.setMaxSimTime(4000000000);
  unawaited(Simulator.run());
  await clk.nextPosedge;
  reset.inject(0);
  await clk.nextPosedge;
  start.inject(1);
  await clk.nextPosedge;
  start.inject(0);

  final hwRng = <int>[];
  final hwGlobal = <List<int>>[];
  var guard = 0;
  while (true) {
    final doneV = t.output('done').value;
    if (doneV.isValid && doneV.toInt() == 1) break;
    if (!doneV.isValid) {
      // ignore: avoid_print
      print('done went X at guard=$guard after ${hwRng.length} symbols');
      break;
    }
    await clk.nextPosedge;
    final sv = t.output('sym_valid').value;
    if (sv.isValid && sv.toInt() == 1) {
      final rv = t.output('rng').value;
      hwRng.add(rv.isValid ? rv.toInt() : -1);
    }
    final bv = t.output('block_valid').value;
    if (bv.isValid && bv.toInt() == 1) {
      final mode = t.output('blk_mode').value;
      if (mode.isValid && (mode.toInt() == 15 || mode.toInt() == 23)) {
        hwGlobal.add([
          t.output('blk_r').value.toInt(),
          t.output('blk_c').value.toInt(),
          t.output('blk_bs').value.toInt(),
          mode.toInt(),
          _asSigned16(t.output('blk_mvrow').value.toInt()),
          _asSigned16(t.output('blk_mvcol').value.toInt()),
        ]);
      }
    }
    if (++guard > 400000) fail('global-motion frame decode timeout');
  }

  var firstDiff = -1;
  final nCmp = hwRng.length < _goldRng.length ? hwRng.length : _goldRng.length;
  for (var i = 0; i < nCmp; i++) {
    if (hwRng[i] != _goldRng[i]) {
      firstDiff = i;
      break;
    }
  }
  if (firstDiff >= 0) {
    // ignore: avoid_print
    print(
      'FIRST DIVERGENCE at symbol $firstDiff: '
      'HW rng=${hwRng[firstDiff]} SW rng=${_goldRng[firstDiff]}',
    );
  }
  // ignore: avoid_print
  print(
    'frame $target: HW decoded ${hwRng.length} symbols; SW '
    '${_goldRng.length}. In-sync through symbol '
    '${firstDiff < 0 ? nCmp - 1 : firstDiff - 1}.',
  );

  expect(firstDiff, equals(-1), reason: 'every od_ec symbol matches SW');
  expect(
    hwRng.length,
    equals(expSyms),
    reason: 'HW decodes all $expSyms symbols',
  );
  expect(hwRng.last, equals(expRng), reason: 'frame-end od_ec rng == $expRng');

  // HW GLOBALMV blocks match SW (position + resolved global MV).
  expect(hwGlobal, equals(_swGlobal), reason: 'HW GLOBALMV blocks == SW');

  await Simulator.endSimulation();
}

int _asSigned16(int v) => (v & 0x8000) != 0 ? v - 0x10000 : v;

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  test(
    'HarborInterFrameWalk: ROTZOOM global-motion frame sync vs SW',
    timeout: const Timeout(Duration(minutes: 40)),
    () async {
      await runGlobalMotionFrame(
        target: 3,
        expSyms: 86,
        expRng: 40608,
        maxBytes: 16,
        // The frame's residual uses only TX_4X16 (13) and TX_8X32 (15).
        txCoeffSizes: const [13, 15],
      );
    },
  );
}
